#!/usr/bin/env bash
# Vynix Panel - One-command update
# Usage: bash <(curl -sL https://raw.githubusercontent.com/OpRGamerz15/VynixPanel/main/update-vynix.sh)

set -euo pipefail

echo "=== Vynix Panel Update ==="
echo "Rebranding to Vynix Panel + adding Purpur/NeoForge..."

# Detect project root
if [ -f "package.json" ] && [ -d "src" ]; then
  ROOT="$(pwd)"
elif [ -f "../package.json" ]; then
  ROOT="$(cd .. && pwd)"
else
  echo "Error: Run this from inside the Jtg / panel repository root."
  exit 1
fi

cd "$ROOT"
echo "Project root: $ROOT"

# Extract update
mkdir -p /tmp/vynix-update
base64 -d << 'B64_EOF' | tar -xzf - -C /tmp/vynix-update

B64_EOF

# Apply files
cp -v /tmp/vynix-update/vynix-panel-update/CreateServer.tsx src/pages/CreateServer.tsx
cp -v /tmp/vynix-update/vynix-panel-update/Dashboard.tsx src/pages/Dashboard.tsx
cp -v /tmp/vynix-update/vynix-panel-update/Layout.tsx src/components/Layout.tsx
cp -v /tmp/vynix-update/vynix-panel-update/jarDownloader.ts src/server/services/jarDownloader.ts
cp -v /tmp/vynix-update/vynix-panel-update/system.ts src/server/routes/system.ts
cp -v /tmp/vynix-update/vynix-panel-update/api.ts src/server/routes/api.ts

echo ""
echo "Files updated. Rebuilding..."
npm run build

echo ""
echo "Restarting panel..."
if command -v pm2 >/dev/null; then
  pm2 restart all || true
else
  echo "PM2 not found. Restart the panel manually."
fi

echo ""
echo "=== Done ==="
echo "Refresh your browser. The panel should now show as Vynix Panel"
echo "with Purpur and NeoForge in the software list."
